    <form method="POST" action="{{ $submitUrl }}" class="mx-auto max-w-6xl space-y-6 py-12 sm:px-6 lg:px-8">@csrf @if($purchase->exists) @method('PUT') @endif
        <div class="grid gap-4 rounded-lg bg-white p-6 shadow sm:grid-cols-3"><div><x-input-label for="supplier_id" :value="__('Supplier *')"/><select id="supplier_id" name="supplier_id" required class="mt-1 block w-full rounded-md border-gray-300">@foreach($suppliers as $supplier)<option value="{{ $supplier->id }}" @selected(old('supplier_id',$purchase->supplier_id)==$supplier->id)>{{ $supplier->name }}</option>@endforeach</select></div><div><x-input-label for="warehouse_id" :value="__('Warehouse *')"/><select id="warehouse_id" name="warehouse_id" required class="mt-1 block w-full rounded-md border-gray-300">@foreach($warehouses as $warehouse)<option value="{{ $warehouse->id }}" @selected(old('warehouse_id',$purchase->warehouse_id)==$warehouse->id)>{{ $warehouse->name }}</option>@endforeach</select></div><div><x-input-label for="expected_at" :value="__('Expected date')"/><input id="expected_at" name="expected_at" type="date" value="{{ old('expected_at',$purchase->expected_at?->format('Y-m-d')) }}" class="mt-1 block w-full rounded-md border-gray-300"></div></div>
        <div class="rounded-lg bg-white p-6 shadow"><div class="mb-4 flex items-center justify-between"><h3 class="font-semibold">Items *</h3><button type="button" @click="addRow()" class="rounded-lg bg-indigo-600 px-3 py-2 text-sm text-white">Add item</button></div><div class="space-y-3"><template x-for="(row,index) in items" :key="row.key"><div class="grid gap-3 md:grid-cols-12"><select :name="`items[${index}][product_id]`" x-model="row.product_id" required class="rounded-md border-gray-300 md:col-span-5"><option value="">Select product</option><template x-for="product in products" :key="product.id"><option :value="product.id" x-text="`${product.name} · ${product.sku}`"></option></template></select><input :name="`items[${index}][quantity]`" x-model="row.quantity" type="number" min="1" required class="rounded-md border-gray-300 md:col-span-2" placeholder="Qty"><input :name="`items[${index}][unit_cost]`" x-model="row.unit_cost" type="number" min="0" step="0.01" required class="rounded-md border-gray-300 md:col-span-4" placeholder="Unit cost"><button type="button" @click="removeRow(row.key)" class="text-red-600 md:col-span-1">×</button></div></template></div></div>
        <div class="grid gap-4 rounded-lg bg-white p-6 shadow sm:grid-cols-4"><div><x-input-label for="discount" :value="__('Discount (Rp)')"/><input id="discount" name="discount" type="number" min="0" step="0.01" value="{{ old('discount',$purchase->discount/100) }}" placeholder="{{ __('e.g. 10000') }}" class="mt-1 block w-full rounded-md border-gray-300"></div><div><x-input-label for="tax" :value="__('Tax (Rp)')"/><input id="tax" name="tax" type="number" min="0" step="0.01" value="{{ old('tax',$purchase->tax/100) }}" placeholder="{{ __('e.g. 2500') }}" class="mt-1 block w-full rounded-md border-gray-300"></div><div><x-input-label for="shipping" :value="__('Shipping (Rp)')"/><input id="shipping" name="shipping" type="number" min="0" step="0.01" value="{{ old('shipping',$purchase->shipping/100) }}" placeholder="{{ __('e.g. 15000') }}" class="mt-1 block w-full rounded-md border-gray-300"></div><div class="flex items-end font-semibold">Total: <span class="ml-2" x-text="money(total)"></span></div><div class="sm:col-span-4"><x-input-label for="notes" :value="__('Notes')"/><textarea id="notes" name="notes" rows="2" placeholder="{{ __('e.g. Supplier invoice number') }}" class="mt-1 block w-full rounded-md border-gray-300">{{ old('notes',$purchase->notes) }}</textarea></div></div><x-primary-button>{{ $purchase->exists ? 'Update purchase' : 'Create purchase' }}</x-primary-button>
