    @push('scripts')<script>document.addEventListener('alpine:init',()=>{Alpine.data('purchaseForm',(products)=>({products,items:[],nextKey:1,init(){@if($purchase->exists)@foreach($purchase->items as $item)this.items.push({key:this.nextKey++,product_id:@js((string)$item->product_id),quantity:@js((string)$item->quantity),unit_cost:@js((string)($item->unit_cost/100))});@endforeach@else this.addRow();@endif},addRow(){this.items.push({key:this.nextKey++,product_id:'',quantity:1,unit_cost:''})},removeRow(key){this.items=this.items.filter(r=>r.key!==key)},get subtotal(){return this.items.reduce((s,r)=>s+(Number(r.quantity)||0)*(Number(r.unit_cost)||0),0)},get discount(){return Math.min(this.subtotal,Number(this.discountValue)||0)},get total(){return Math.max(0,this.subtotal-this.discount)+(Number(this.taxValue)||0)+(Number(this.shippingValue)||0)},discountValue:0,taxValue:0,shippingValue:0,money(v){return 'Rp '+Number(v||0).toLocaleString('id-ID')}}))});</script>@endpush
